mapper.select:
SELECT u.class_name as class_name, COUNT(a.id) as award_count FROM award a JOIN team_info ti ON a.team_id = ti.id JOIN team_member_teacher tmt ON ti.id = tmt.team_id JOIN team_member_student tms ON ti.id = tms.team_id JOIN user_info u ON tms.student_id = u.id WHERE tmt.teacher_id = #{teacherId}
AND u.major = #{major}
AND u.class_name = #{sClass}
AND ti.type = #{projectType}
AND ti.year = #{year}
GROUP BY u.class_name ORDER BY award_count DESC

SELECT u.name as student_name, CONCAT(u.major_name, '-', u.class_name) as major_class, COALESCE(s.total_score, 0) as total_score, st.skill_name as skill_name FROM team_member_teacher tmt JOIN team_info ti ON tmt.team_id = ti.id JOIN team_member_student tms ON ti.id = tms.team_id JOIN user_info u ON tms.student_id = u.id LEFT JOIN score s ON u.id = s.user_id LEFT JOIN user_skill us ON u.id = us.user_id LEFT JOIN skill_tag st ON us.skill_id = st.id WHERE tmt.teacher_id = #{teacherId}
AND u.major = #{major}
AND u.class_name = #{sClass}
AND ti.type = #{projectType}
AND ti.year = #{year}
ORDER BY total_score DESC
